// Typecheck of every package, cross-platform: `bun check`.
// Three TypeScript projects, because their global types cannot be mixed:
//   tsconfig.json                      protocol, driver-ev3, driver-ev3dev, sim-world, sim-ev3, runtime, scripts (bun + DOM)
//   packages/server/tsconfig.json       the Worker (workerd types generated by `wrangler types`)
//   packages/server/test/tsconfig.json  the relay's tests and scripts (bun)
import { join } from "node:path";

const root = join(import.meta.dir, "..");
const relay = join(root, "packages", "server");
const run = async (name: string, args: string[], cwd: string): Promise<boolean> => {
  const t = Date.now();
  const child = Bun.spawn([process.execPath, "x", ...args], { cwd, stdin: "ignore", stdout: "pipe", stderr: "pipe" });
  const [out, err, code] = await Promise.all([
    new Response(child.stdout).text(),
    new Response(child.stderr).text(),
    child.exited,
  ]);
  // one block per project so parallel output does not interleave
  if (code !== 0) process.stderr.write(out + err);
  console.log(`${code === 0 ? "ok  " : "FAIL"} ${name} (${Date.now() - t} ms)`);
  return code === 0;
};

// worker-configuration.d.ts is generated (gitignored): the relay project cannot be checked without it
if (!(await run("wrangler types", ["wrangler", "types", "--strict-vars=false"], relay))) process.exit(1);
const projects = ["tsconfig.json", "packages/server/tsconfig.json", "packages/server/test/tsconfig.json"];
const ok = await Promise.all(projects.map((p) => run(`tsc -p ${p}`, ["tsc", "-p", join(root, ...p.split("/"))], root)));
process.exit(ok.every(Boolean) ? 0 : 1);
